class Solution {
    public void flatten(TreeNode root) {
        TreeNode curr = root;

        while (curr != null) {
            if (curr.left != null) {
                TreeNode rightmost = curr.left;
                while (rightmost.right != null) {
                    rightmost = rightmost.right;
                }

                rightmost.right = curr.right;
                curr.right = curr.left;
                curr.left = null;
            }
            curr = curr.right;
        }
    }
}

class Solution {
    private TreeNode prev = null;

    public void flatten(TreeNode root) {
        if (root == null) return;

        flatten(root.right);
        flatten(root.left);

        root.right = prev;
        root.left = null;
        prev = root;
    }
}

import java.util.*;

class Solution {
    public void flatten(TreeNode root) {
        if (root == null) {
            return;
        }

        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        TreeNode previous = null;

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            if (previous != null) {
                previous.left = null;
                previous.right = node;
            }

            if (node.right != null) {
                stack.push(node.right);
            }
            if (node.left != null) {
                stack.push(node.left);
            }
            previous = node;
        }

        previous.left = null;
    }
}

class Solution {
    public void flatten(TreeNode root) {
        flattenAndReturnTail(root);
    }

    private TreeNode flattenAndReturnTail(TreeNode node) {
        if (node == null) {
            return null;
        }

        TreeNode leftTail = flattenAndReturnTail(node.left);
        TreeNode rightTail = flattenAndReturnTail(node.right);

        if (leftTail != null) {
            leftTail.right = node.right;
            node.right = node.left;
            node.left = null;
        }

        if (rightTail != null) {
            return rightTail;
        }
        if (leftTail != null) {
            return leftTail;
        }
        return node;
    }
}
